CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';
SET SESSION autocommit = 0;
-- Add the observed cooking recipe offer
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`entry` int unsigned NOT NULL, `slot` smallint NOT NULL, `item` int NOT NULL, `maxcount` int unsigned NOT NULL, `incrtime` int unsigned NOT NULL, `ExtendedCost` int unsigned NOT NULL, `type` tinyint unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `IgnoreFiltering` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`entry`, `item`, `ExtendedCost`, `type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `type`, `PlayerConditionID`, `IgnoreFiltering`, `VerifiedBuild`, `note`) VALUES
(11189, 0, 250173, 0, 0, 0, 1, 0, 0, 0, 'WoW-Professions and Wowhead: Qia sells recipe; client buy price 20000; stock provisional');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `npc_vendor` t WHERE t.`entry` = s.`entry` AND t.`item` = s.`item` AND t.`ExtendedCost` = s.`ExtendedCost` AND t.`type` = s.`type`) AND EXISTS (SELECT 1 FROM `creature_template` t JOIN `creature` c ON c.`id`=t.`entry`
 WHERE t.`entry`=s.`entry` AND t.`name`='Qia' AND c.`map`=1
 AND (COALESCE(c.`npcflag`,t.`npcflag`) & 128)=128)
AND NOT EXISTS (SELECT 1 FROM `npc_vendor` v WHERE v.`entry`=s.`entry` AND (v.`item`=s.`item` OR v.`item`<0))
AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl`='npc_vendor'
 AND r.`k1`=s.`entry` AND r.`k2`=s.`item`);
INSERT INTO `npc_vendor` (`entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `type`, `PlayerConditionID`, `IgnoreFiltering`, `VerifiedBuild`) SELECT `entry`, `slot`, `item`, `maxcount`, `incrtime`, `ExtendedCost`, `type`, `PlayerConditionID`, `IgnoreFiltering`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `k4`, `file`, `note`) SELECT 'npc_vendor', s.`entry`, s.`item`, s.`ExtendedCost`, s.`type`, '2026_11_10_56_world_everlake_import_qia01.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_56_world_everlake_import_qia01.sql', `note` = s.`note`;
